using System;using System.Threading.Tasks;using Microsoft.Web.WebView2.Core;using System.IO;using System.Reflection;using System.Drawing;using System.Diagnostics;using System.Windows.Forms;using Microsoft.Web.WebView2.WinForms;
internal static class NativeMenuRenderProbe {
 [STAThread]static int Main(string[] args){Application.EnableVisualStyles();var config=PetFiles.Json.Deserialize<PetConfig>(File.ReadAllText(args[0]));DshPetMenu menu=null;var loop=new ApplicationContext();var timer=new Timer{Interval=100};var deadline=DateTime.UtcNow.AddSeconds(25);int phase=0,navigations=0,before=0;var watch=new Stopwatch();Exception failure=null;
  menu=new DshPetMenu(config,v=>{},()=>{},p=>{failure=new Exception("Menu fallback: "+menu.Error);loop.ExitThread();});var web=(WebView2)typeof(DshPetMenu).GetField("web",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(menu);var ready=typeof(DshPetMenu).GetField("documentReady",BindingFlags.Instance|BindingFlags.NonPublic);menu.Text="NewMate · 菜单渲染验收";if(args.Length>1)menu.ShowInTaskbar=true;menu.Warm();
  timer.Tick+=delegate {try {if(web.CoreWebView2!=null&&phase==0){web.CoreWebView2.NavigationCompleted+=delegate{navigations++;};phase=1;}if(phase==1&&(bool)ready.GetValue(menu)){before=navigations;watch.Restart();menu.Present(new Point(500,250),1,new Rectangle(420,280,64,64));if(!menu.Open)throw new Exception("Warmed menu not immediately visible");watch.Stop();Console.WriteLine("PASS prewarmed native menu visible in "+watch.ElapsedMilliseconds+" ms");phase=2;deadline=DateTime.UtcNow.AddMilliseconds(300);}if(phase==2&&DateTime.UtcNow>deadline){if(!menu.Open)throw new Exception("Menu self-dismissed before the next gesture");menu.Dismiss();phase=3;deadline=DateTime.UtcNow.AddMilliseconds(200);}if(phase==3&&DateTime.UtcNow>deadline){menu.Present(new Point(500,250),1,new Rectangle(420,280,64,64));if(!menu.Open)throw new Exception("Cached reopen failed");phase=4;deadline=DateTime.UtcNow.AddSeconds(args.Length>1?25:1);}if(phase==4&&DateTime.UtcNow>deadline){if(!menu.Open)throw new Exception("Menu self-dismissed after cached reopen");if(navigations!=before)throw new Exception("Reopen navigated the WebView");Console.WriteLine("PASS cached reopen reused the loaded WebView without navigation");if(menu.Width<70||menu.Height<70||menu.Width>1600||menu.Height>1600)throw new Exception("Invalid menu geometry");Console.WriteLine("PASS actual WebView menu geometry "+menu.Width+"x"+menu.Height);var image=Path.Combine(config.directory,"render.png");var output=File.Create(image);phase=5;deadline=DateTime.UtcNow.AddSeconds(10);web.CoreWebView2.CapturePreviewAsync(CoreWebView2CapturePreviewImageFormat.Png,output).ContinueWith(task=>{output.Dispose();if(task.IsFaulted)failure=task.Exception;else Console.WriteLine("RENDER_IMAGE "+image);loop.ExitThread();},TaskScheduler.FromCurrentSynchronizationContext());}else if(DateTime.UtcNow>deadline)throw new Exception("Menu warm-up timeout: "+menu.Error);}catch(Exception e){failure=e;loop.ExitThread();}};timer.Start();Application.Run(loop);timer.Dispose();menu.Dispose();if(failure!=null)throw failure;return 0;
 }
}
